"""Argmax over a dimension (dim=1) of a 3D tensor."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': '51_Argmax_over_a_dimension',
    'batch_size': 16,
    'dim1': 2048,
    'dim2': 2048,
    'dim': 1,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    x = jax.random.uniform(
        key, (CONFIG['batch_size'], CONFIG['dim1'], CONFIG['dim2']), dtype=dtype
    )
    return (x,)


def workload(x):
    return jnp.argmax(x, axis=CONFIG['dim'])

"""BPR-max loss: softmax(dim=1) * sigmoid(diag - logit), mean, -log."""
import jax
import jax.numpy as jnp

CONFIG = {'name': 'BPR_max_2229', 'n': 8192}


def create_inputs(dtype=jnp.float32):
    n = CONFIG['n']
    logit = jax.random.uniform(jax.random.key(0), (n, n), dtype)
    return (logit,)


def workload(logit):
    logit_softmax = jax.nn.softmax(logit, axis=1)
    diff = jnp.diagonal(logit)[:, None] - logit
    return -jnp.log(jnp.mean(logit_softmax * jax.nn.sigmoid(diff)))

